import CIimgui

extension IconKey {
    /// Codepoint of this icon's glyph in the application icon font.
    var codepoint: ImWchar {
        switch self {
        case .add: 0xEFCD
        case .arrowComment: 0xEFCE
        case .arrowOutlined: 0xEFCF
        case .arrowParameter: 0xEFD0
        case .cancel: 0xEFD1
        case .chevronsLeft: 0xEFD2
        case .chevronsRight: 0xEFD3
        case .connect: 0xEFD4
        case .delete: 0xEFD5
        case .empty: 0xEFD6
        case .error: 0xEFD7
        case .formula: 0xEFD8
        case .hand: 0xEFD9
        case .handleFlow: 0xEFDA
        case .lastStep: 0xEFDB
        case .lineCurved: 0xEFDC
        case .lineOrthogonal: 0xEFDD
        case .lineStraight: 0xEFDE
        case .loop: 0xEFDF
        case .menu: 0xEFE0
        case .nextStep: 0xEFE1
        case .ok: 0xEFE2
        case .place: 0xEFE3
        case .previousStep: 0xEFE4
        case .redo: 0xEFE5
        case .restart: 0xEFE6
        case .run: 0xEFE7
        case .select: 0xEFE8
        case .stop: 0xEFE9
        case .timeWindow: 0xEFEA
        case .undo: 0xEFEB
        case .zoomIn: 0xEFEC
        case .zoomOut: 0xEFED
        }
    }

    /// The icon as a one-character string, to draw with the current font and colour.
    var text: String {
        String(UnicodeScalar(codepoint)!)
    }

    /// Glyph range covering every icon, for `AddFontFromFileTTF` for ImGui.
    ///
    static let glyphRanges: [ImWchar] = [0xEFCD, 0xEFED, 0]
}
